namespace RonSijm.FluidHumidifier.Factories.Lambda;

public class MicrovmImageFactory(string resourceName = null, Action<Humidifier.Lambda.MicrovmImage> factoryAction = null) : ResourceFactory<Humidifier.Lambda.MicrovmImage>(resourceName)
{

    internal List<InnerMicrovmImageCpuConfigurationFactory> CpuConfigurationsFactories { get; set; } = [];

    internal List<InnerMicrovmImageEnvironmentVariableFactory> EnvironmentVariablesFactories { get; set; } = [];

    internal List<InnerMicrovmImageResourcesFactory> ResourcesFactories { get; set; } = [];

    internal InnerMicrovmImageLoggingFactory LoggingFactory { get; set; }

    internal InnerMicrovmImageCodeArtifactFactory CodeArtifactFactory { get; set; }

    internal InnerMicrovmImageHooksFactory HooksFactory { get; set; }

    protected override Humidifier.Lambda.MicrovmImage Create()
    {
        var microvmImageResult = CreateMicrovmImage();
        factoryAction?.Invoke(microvmImageResult);

        return microvmImageResult;
    }

    private Humidifier.Lambda.MicrovmImage CreateMicrovmImage()
    {
        var microvmImageResult = new Humidifier.Lambda.MicrovmImage
        {
            GivenName = InputResourceName,
        };

        return microvmImageResult;
    }
    public override void CreateChildren(Humidifier.Lambda.MicrovmImage result)
    {
        base.CreateChildren(result);

        result.CpuConfigurations = CpuConfigurationsFactories.Any() ? CpuConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.EnvironmentVariables = EnvironmentVariablesFactories.Any() ? EnvironmentVariablesFactories.Select(x => x.Build()).ToList() : null;
        result.Resources = ResourcesFactories.Any() ? ResourcesFactories.Select(x => x.Build()).ToList() : null;
        result.Logging ??= LoggingFactory?.Build();
        result.CodeArtifact ??= CodeArtifactFactory?.Build();
        result.Hooks ??= HooksFactory?.Build();
    }

} // End Of Class

